<?php /* VIVA NOTE: Room image gallery; files are uploaded through the room controller. */ ?><div class="toolbar"><p>Photo gallery · <?=e($room['room_label']?:'Room #'.$room['room_id'])?></p><a href="<?=e(url('/room/show',['id'=>$room['room_id']]))?>">← Room</a></div>
<section class="panel"><h3>Upload room photo</h3><form method="post" action="<?=e(url('/room/photos/upload',['id'=>$room['room_id']]))?>" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><label>Photo (JPG, PNG, WebP; max 5MB)<input name="photo" type="file" accept="image/png,image/jpeg,image/webp" required></label><label>Caption<input name="caption" maxlength="255"></label><button class="btn">Upload</button></form></section>
<div class="gallery"><?php foreach($photos as $photo):?><article class="photo-card"><img alt="<?=e($photo['caption']?:'Room photo')?>" loading="lazy" src="<?=e(url('/'.$photo['file_path']))?>"><p><?=e($photo['caption']?:'Room photo')?></p><form method="post" action="<?=e(url('/room/photos/delete',['id'=>$room['room_id']]))?>" data-confirm="Delete this photo?"><?=csrf_field()?><input type="hidden" name="photo_id" value="<?=e($photo['photo_id'])?>"><button class="btn small danger">Remove</button></form></article><?php endforeach;?><?php if(!$photos):?><p class="empty">No room photos uploaded yet.</p><?php endif;?></div>
